"""Stripe webhook endpoint (stdlib-only, no framework required).

Handles `payment_intent.succeeded` and `payment_intent.payment_failed`
events with signature verification and idempotent processing.

Run:
    python webhook_endpoint.py

Expose this URL to Stripe as your webhook endpoint (e.g.
https://yourdomain.com/webhook) and set the signing secret
(whsec_...) via the STRIPE_WEBHOOK_SECRET env var.
"""

import hashlib
import hmac
import json
import os
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

# Optional: if the `stripe` library is installed, use its battle-tested
# `Webhook.construct_event` for signature verification and parsing.
try:
    import stripe

    def _construct_event(payload, sig_header, secret):
        return stripe.Webhook.construct_event(payload, sig_header, secret)

    SignatureVerificationError = stripe.error.SignatureVerificationError

except ImportError:  # pragma: no cover - fallback path
    stripe = None

    class SignatureVerificationError(Exception):
        pass

    def _construct_event(payload, sig_header, secret):
        _verify_signature_manual(payload, sig_header, secret)
        try:
            return json.loads(payload.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            raise ValueError("Invalid payload")


def _verify_signature_manual(payload, sig_header, secret):
    """Verify a Stripe webhook signature without the stripe library.

    Scheme: the `Stripe-Signature` header contains `t=<timestamp>,v1=<sig>`
    where v1 = HMAC-SHA256(secret, f"{t}.{payload}") hexdigest.
    """
    try:
        params = dict(item.split("=", 1) for item in sig_header.split(","))
    except ValueError:
        raise SignatureVerificationError("Malformed signature header")

    timestamp = params.get("t")
    signature = params.get("v1")
    if not timestamp or not signature:
        raise SignatureVerificationError("Missing t or v1 parameter")

    signed_payload = f"{timestamp}.{payload.decode('utf-8')}".encode("utf-8")
    expected = hmac.new(
        secret.encode("utf-8"), signed_payload, hashlib.sha256
    ).hexdigest()

    if not hmac.compare_digest(expected, signature):
        raise SignatureVerificationError("Signature does not match")


endpoint_secret = os.environ.get("STRIPE_WEBHOOK_SECRET", "")

# In production, replace this with your durable event store (e.g. a DB table
# keyed on event id) so the check survives process restarts.
_processed_event_ids = set()


# ---------------------------------------------------------------------------
# Business logic (kept separate from HTTP handling so it is unit-testable)
# ---------------------------------------------------------------------------

def handle_successful_payment(payment_intent):
    """Process a `payment_intent.succeeded` event.

    The client-side redirect is not reliable (users can close the tab),
    so fulfillment must be driven from this webhook.
    """
    payment_intent_id = payment_intent["id"]
    customer_id = payment_intent.get("customer")
    amount = payment_intent["amount"]
    currency = payment_intent["currency"]
    metadata = payment_intent.get("metadata", {}) or {}

    # Update your database / fulfill the order here, e.g.:
    #   order_id = metadata.get("order_id")
    #   mark_order_paid(order_id, payment_intent_id)
    #   send_confirmation_email(customer_id, amount, currency)

    print(
        f"[payment_intent.succeeded] {payment_intent_id} "
        f"customer={customer_id} amount={amount} {currency} "
        f"metadata={metadata}"
    )
    return {"status": "fulfilled", "payment_intent_id": payment_intent_id}


def handle_failed_payment(payment_intent):
    """Process a `payment_intent.payment_failed` event."""
    payment_intent_id = payment_intent["id"]
    customer_id = payment_intent.get("customer")
    error = payment_intent.get("last_payment_error") or {}
    decline_code = error.get("decline_code")
    message = error.get("message", "Payment failed")

    # Update order status / notify the customer here, e.g.:
    #   order_id = payment_intent.get("metadata", {}).get("order_id")
    #   mark_order_failed(order_id, decline_code)
    #   notify_payment_failed(customer_id, message)

    print(
        f"[payment_intent.payment_failed] {payment_intent_id} "
        f"customer={customer_id} decline_code={decline_code} "
        f"message={message}"
    )
    return {"status": "recorded", "payment_intent_id": payment_intent_id}


# Map event types to handlers. Add new events here as needed.
EVENT_HANDLERS = {
    "payment_intent.succeeded": handle_successful_payment,
    "payment_intent.payment_failed": handle_failed_payment,
}


def is_event_processed(event_id):
    """Return True if the event was already handled (idempotency check)."""
    return event_id in _processed_event_ids


def mark_event_processed(event_id):
    """Record the event as handled so Stripe retries do not double-process."""
    _processed_event_ids.add(event_id)


def process_event(event):
    """Dispatch a verified Stripe event to its handler, exactly once."""
    event_id = event["id"]
    event_type = event["type"]

    if is_event_processed(event_id):
        print(f"[webhook] duplicate event {event_id} skipped")
        return {"status": "duplicate", "event_id": event_id}

    handler = EVENT_HANDLERS.get(event_type)
    if handler is None:
        # Unknown event types are acknowledged but not processed.
        print(f"[webhook] unhandled event type {event_type}")
        return {"status": "ignored", "event_type": event_type}

    result = handler(event["data"]["object"])
    mark_event_processed(event_id)
    return result


def handle_request(payload, sig_header):
    """Process one webhook HTTP request. Returns (status_code, json_dict)."""
    if not sig_header:
        return 400, {"error": "Missing Stripe-Signature header"}

    try:
        event = _construct_event(payload, sig_header, endpoint_secret)
    except ValueError:
        return 400, {"error": "Invalid payload"}
    except SignatureVerificationError:
        return 400, {"error": "Invalid signature"}

    try:
        result = process_event(event)
    except Exception as exc:  # pragma: no cover - defensive
        # Do NOT mark the event processed; Stripe will retry the delivery.
        print(f"[webhook] processing failed for {event.get('id')}: {exc}")
        return 500, {"error": "Event processing failed"}

    # Stripe expects a 2xx response to stop retrying delivered events.
    return 200, result


# ---------------------------------------------------------------------------
# HTTP server
# ---------------------------------------------------------------------------

class WebhookHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        try:
            length = int(self.headers.get("Content-Length", 0))
        except ValueError:
            length = 0
        payload = self.rfile.read(length) if length > 0 else b""
        sig_header = self.headers.get("Stripe-Signature")
        status, body = handle_request(payload, sig_header)
        self._respond(status, body)

    def do_GET(self):
        if self.path.rstrip("/") == "/health":
            self._respond(200, {"status": "ok"})
        else:
            self._respond(404, {"error": "Not found"})

    def _respond(self, status, body):
        encoded = json.dumps(body).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(encoded)))
        self.end_headers()
        self.wfile.write(encoded)

    def log_message(self, fmt, *args):  # quieter default logging
        print(f"[http] {self.address_string()} - {fmt % args}")


def main():
    port = int(os.environ.get("PORT", 5000))
    if not endpoint_secret:
        print(
            "WARNING: STRIPE_WEBHOOK_SECRET is not set; "
            "all webhook deliveries will be rejected.",
            file=sys.stderr,
        )
    server = ThreadingHTTPServer(("0.0.0.0", port), WebhookHandler)
    print(f"Webhook endpoint listening on http://0.0.0.0:{port}/webhook")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down.")
        server.server_close()


if __name__ == "__main__":
    main()

